test("押すと、渡した手続きが 1 回呼ばれる", () => {
  const clicks: string[] = [];
  render(
    <Button
      kind={ButtonKinds.Primary}
      size={ButtonSizes.Regular}
      onClick={() => clicks.push("clicked")}
    >
      保存
    </Button>,
  );

  fireEvent.click(screen.getByRole("button", { name: "保存" }));

  expect(clicks).toHaveLength(1);
});

test("押させたくないときは、押せない状態で出る", () => {
  render(
    <Button kind={ButtonKinds.Primary} size={ButtonSizes.Regular} disabled>
      保存
    </Button>,
  );

  expect(
    screen.getByRole("button", { name: "保存" }).hasAttribute("disabled"),
  ).toBe(true);
});

test("押させたくないときは、押しても手続きが呼ばれない", () => {
  const clicks: string[] = [];
  render(
    <Button
      kind={ButtonKinds.Primary}
      size={ButtonSizes.Regular}
      disabled
      onClick={() => clicks.push("clicked")}
    >
      保存
    </Button>,
  );

  fireEvent.click(screen.getByRole("button", { name: "保存" }));

  expect(clicks).toHaveLength(0);
});

test("フォームの中に置いても、押してフォームを送信しない", () => {
  const submits: string[] = [];
  render(
    <form
      onSubmit={(event) => {
        event.preventDefault();
        submits.push("submitted");
      }}
    >
      <Button kind={ButtonKinds.Secondary} size={ButtonSizes.Regular}>
        保存
      </Button>
    </form>,
  );

  fireEvent.click(screen.getByRole("button", { name: "保存" }));

  expect(submits).toHaveLength(0);
});

test("中身の綴りがボタンの名前になる", () => {
  render(
    <Button kind={ButtonKinds.Danger} size={ButtonSizes.Regular}>
      Delete token
    </Button>,
  );

  expect(screen.getByRole("button", { name: "Delete token" })).toBeDefined();
});

test("名前を与えると、中身ではなくその名前で読まれる", () => {
  render(
    <Button
      kind={ButtonKinds.Primary}
      size={ButtonSizes.Small}
      aria-label="card を表示"
    >
      Reveal
    </Button>,
  );

  expect(screen.getByRole("button", { name: "card を表示" })).toBeDefined();
});

test("アイコンのボタンは、与えた名前で読まれる", () => {
  render(
    <Button kind={ButtonKinds.Icon} aria-label="追加">
      +
    </Button>,
  );

  expect(screen.getByRole("button", { name: "追加" })).toBeDefined();
});

test("テキストのボタンは、名前を与えなければ中身の綴りで読まれる", () => {
  render(<Button kind={ButtonKinds.Text}>reveal in tree</Button>);

  expect(screen.getByRole("button", { name: "reveal in tree" })).toBeDefined();
});

test("テキストのボタンは、名前を与えるとその名前で読まれる", () => {
  render(
    <Button kind={ButtonKinds.Text} aria-label="card をツリーで表示">
      reveal in tree
    </Button>,
  );

  expect(
    screen.getByRole("button", { name: "card をツリーで表示" }),
  ).toBeDefined();
});

test("押せない理由を添えると、ボタンの title に出る", () => {
  render(
    <Button
      kind={ButtonKinds.Emphasis}
      size={ButtonSizes.Regular}
      disabled
      title="選んでから押せます"
    >
      Create component
    </Button>,
  );

  expect(
    screen
      .getByRole("button", { name: "Create component" })
      .getAttribute("title"),
  ).toBe("選んでから押せます");
});

test("押せない理由を添えなければ、title は出ない", () => {
  render(
    <Button kind={ButtonKinds.Emphasis} size={ButtonSizes.Regular}>
      Create component
    </Button>,
  );

  expect(
    screen
      .getByRole("button", { name: "Create component" })
      .hasAttribute("title"),
  ).toBe(false);
});

test("アイコンは、名前を与えないと型エラーになる", () => {
  // @ts-expect-error アイコンには綴りが無いので aria-label が要る
  const props: ButtonProps = { kind: ButtonKinds.Icon, children: "+" };

  expect(props.kind).toBe(ButtonKinds.Icon);
});

test("アイコンには大きさを渡せない", () => {
  // @ts-expect-error アイコンの大きさは 30px に決まっている
  const props: ButtonProps = {
    kind: ButtonKinds.Icon,
    "aria-label": "追加",
    size: ButtonSizes.Regular,
    children: "+",
  };

  expect(props.kind).toBe(ButtonKinds.Icon);
});

test("テキストには大きさを渡せない", () => {
  // @ts-expect-error テキストは行内に置き、高さを持たない
  const props: ButtonProps = {
    kind: ButtonKinds.Text,
    size: ButtonSizes.Regular,
    children: "reveal in tree",
  };

  expect(props.kind).toBe(ButtonKinds.Text);
});

test("テキストは、名前を与えなくても型が通る", () => {
  const props: ButtonProps = {
    kind: ButtonKinds.Text,
    children: "reveal in tree",
  };

  expect(props.kind).toBe(ButtonKinds.Text);
});

test("箱型は、大きさを渡さないと型エラーになる", () => {
  // @ts-expect-error 箱型は大きさが要る
  const props: ButtonProps = { kind: ButtonKinds.Primary, children: "保存" };

  expect(props.kind).toBe(ButtonKinds.Primary);
});

test("語彙に無い種類の文字列は渡せない", () => {
  const props: ButtonProps = {
    // @ts-expect-error 種類は ButtonKinds の値に閉じている
    kind: "Link",
    size: ButtonSizes.Regular,
    children: "保存",
  };

  expect(props.kind).toBe("Link");
});

test("表示のボタンを押すと、その行が指すノード名が通知される", async () => {
  const onReveal = vi.fn();
  render(
    <DocumentErrorList
      errors={MixedErrors}
      origin={DocumentErrorOrigins.OpenedFile}
      onReveal={onReveal}
      onRevertFile={vi.fn()}
      isReverting={false}
    />,
  );

  // 先頭ではなく 2 つ目を押す（先頭固定の実装で通らないようにする）
  await userEvent.click(screen.getByRole("button", { name: "cta を表示" }));

  expect(onReveal).toHaveBeenCalledWith("cta");
});

test("書き戻しの最中は、書き戻しを押し直せない", () => {
  render(
    <DocumentErrorList
      errors={MixedErrors}
      origin={DocumentErrorOrigins.OpenedFile}
      onReveal={vi.fn()}
      onRevertFile={vi.fn()}
      isReverting
    />,
  );

  expect(
    screen
      .getByRole("button", { name: "revert file" })
      .hasAttribute("disabled"),
  ).toBe(true);
});

test("そのインスタンスしか無いときはまとめて選ぶボタンを押せない", () => {
  renderMultiInstanceSelected("home-card");

  expect(
    screen.getByRole("button", { name: "Select all 1 instances" }),
  ).toHaveProperty("disabled", true);
});

test("使えない部品名のときはボタンにその旨が添えられる", async () => {
  const user = userEvent.setup();
  const input = setupInput(Option.some("home-panel"));
  render(
    <CreateComponent
      document={input.document}
      singleName={input.singleName}
      isFrozen={false}
      onCreate={() => {}}
    />,
  );

  await user.click(screen.getByRole("button", { name: /Create component/ }));
  await user.type(
    screen.getByRole("textbox", { name: "部品名" }),
    "Info Panel",
  );

  expect(
    screen
      .getByRole("button", { name: /Create component/ })
      .getAttribute("title"),
  ).toBe("使える部品名を入れると作成できます");
});
